function hand(mat,name,nf){const h=new THREE.Group();h.name=name;h.add(ell(mat,0.2,0.1,0.2,0.05,0,0,'palm'));
  for(let i=0;i<nf;i++){const t=i/(nf-1)-0.5;const f=limb(mat,V(0.15,0,t*0.34),V(0.46-Math.abs(t)*0.1,-0.05,t*0.52),0.06,0.05);f.name='finger-'+i;h.add(f);}
