function arm(parent,name,S,E,Hd,r0,r1,r2,mat){const g=grp(name,parent,S.x,S.y,S.z);
  const u=limb(mat,V(0,0,0),E,r0,r1);u.name='upper';const l=limb(mat,E,Hd,r1,r2);l.name='lower';g.add(u,l);return g;}
function leg(parent,name,Hp,K,F,mat){const g=grp(name,parent,Hp.x,Hp.y,Hp.z);
